import{_ as p,a as e}from"./chunks/dwrw-pc2.6ca31931.js";import{_ as t,o as r,c as o,O as s}from"./chunks/framework.b9c6cb60.js";const h="/assets/dwrw-pc3.6223a7be.png",n="/assets/ddrw-cp1.1127d835.png",a="/assets/ddrw-cp2.91a1940b.png",i="/assets/ddrw-cp3.6efaa6ac.png",d="/assets/ddrw-wl1.bd7481b9.png",c="/assets/ddrw-wl2.971c1a86.png",g=JSON.parse('{"title":"生产安排","description":"","frontmatter":{},"headers":[],"relativePath":"生产管理/生产计划/生产安排.md","filePath":"生产管理/生产计划/生产安排.md"}'),u={name:"生产管理/生产计划/生产安排.md"};function _(m,l,b,q,f,k){return r(),o("div",null,l[0]||(l[0]=[s('<h1 id="生产安排" tabindex="-1">生产安排 <a class="header-anchor" href="#生产安排" aria-label="Permalink to &quot;生产安排&quot;">​</a></h1><blockquote><p>销售订单完成排单后，生产安排列表根据销售订单生成对应的任务,目前分为批次维度和产品维度</p></blockquote><h2 id="_1-批次维度" tabindex="-1">1.批次维度 <a class="header-anchor" href="#_1-批次维度" aria-label="Permalink to &quot;1.批次维度&quot;">​</a></h2><ul><li>可通过单号，和交期的时间进行查询</li><li>退回功能：未进行安排时，可退回操作。(退回操作后数据返回到销售订单列表中，状态成为未处理状态，可重新进行排单)</li><li>在安排时可使用库存，生产，采购</li><li>一键操作：当前批次中所有产品库存均满足时，可一键安排使用库存</li><li>物料表：点击显示这个产品所需的配套物料</li></ul><p><img src="'+p+'" alt="如图所示"></p><h4 id="_1-批次维度走生产" tabindex="-1">1.批次维度走生产 <a class="header-anchor" href="#_1-批次维度走生产" aria-label="Permalink to &quot;1.批次维度走生产&quot;">​</a></h4><ul><li><p>如果这个产品有工艺路线，工艺路线是内部路线时可走生产安排</p></li><li><p>点击进入弹窗设置生产数量</p><p>-生产加工时可使用库存，采购，委外加工，如果生产的这个零件/物料有工艺路线时还可以走生产</p></li><li><p>如果库存满足时可一键使用库存，采购零件也可一键点击设置</p></li><li><p>安排生产时已安排量不能超过需求数量，超过将无法安排</p></li></ul><p><img src="'+e+'" alt="如图所示"></p><h4 id="_2-批次维度走采购" tabindex="-1">2.批次维度走采购 <a class="header-anchor" href="#_2-批次维度走采购" aria-label="Permalink to &quot;2.批次维度走采购&quot;">​</a></h4><ul><li><p>可走采购安排，采购安排的信息会流转到采购管理-缺料列表中进行分发，询价完结等</p></li><li><p>如果这个产品有工艺路线，工艺路线是外部路线时可走采购安排</p></li><li><p>击进入弹窗设置采购数量</p><p>-可直接采购成品或委外加工</p></li><li><p>如果库存满足时可一键使用库存，采购零件也可一键点击设置</p></li><li><p>安排采购时已安排量不能超过需求数量，超过将无法安排</p></li></ul><p><img src="'+h+'" alt="如图所示"></p><h2 id="_2-产品维度安排" tabindex="-1">2.产品维度安排 <a class="header-anchor" href="#_2-产品维度安排" aria-label="Permalink to &quot;2.产品维度安排&quot;">​</a></h2><ul><li>可通过编号，单号，名称/型号，开始，结束时间进行查询</li><li>退回功能：未进行安排时，可退回操作。(退回操作后数据返回到销售订单列表中，状态成为未处理状态，可重新进行排单)</li><li>BOM表：点击可查看这个产品所用到的物料名称</li></ul><h4 id="_1-批量安排" tabindex="-1">1.批量安排 <a class="header-anchor" href="#_1-批量安排" aria-label="Permalink to &quot;1.批量安排&quot;">​</a></h4><ul><li>只支持相同产品的合并安排</li><li>可使用库存，走采购，走生产</li><li>库存满足时支持一键使用库存</li></ul><h1 id="调度任务—产品" tabindex="-1">调度任务—产品 <a class="header-anchor" href="#调度任务—产品" aria-label="Permalink to &quot;调度任务—产品&quot;">​</a></h1><blockquote><p>调度任务数据来源：销售订单完成排单后，调度任务列表根据销售订单生成对应的调度任务,目前分为批次维度和产品维度。</p></blockquote><h4 id="_1-产品维度安排" tabindex="-1">1.产品维度安排 <a class="header-anchor" href="#_1-产品维度安排" aria-label="Permalink to &quot;1.产品维度安排&quot;">​</a></h4><ul><li><p>可通过批次号，产品名称，产品型号，产品交期进行数据筛选</p></li><li><p>退回功能：一个批次中的产品未进行过安排，可进行退回操作。(退回操作后数据返回到销售订单列表中，可重新进行排单)</p></li><li><p>当安排的产品有工艺路线时，可以通过库存，采购（包含采购成品和外协加工数量），生产方式进行调度安排</p></li><li><p>本次安排数量：使用库存数量+采购数量（采购成品+外协加工数量）+生产数量</p></li><li><p>待安排数量：订单数量-已安排数量</p></li><li><p>生产数量计算规则：以能满足生产的产品数量的最小配套零件进行计算</p><p>-例如：A产品生产需要配套3个B产品，2个C产品，调度安排生产时，提供了9个B产品，4个C产品，则生产数量为2个</p></li></ul><p><img src="'+n+'" alt="如图所示"></p><h4 id="_2-产品维度走生产" tabindex="-1">2.产品维度走生产 <a class="header-anchor" href="#_2-产品维度走生产" aria-label="Permalink to &quot;2.产品维度走生产&quot;">​</a></h4><ul><li><p>如果这个产品有工艺路线，工艺路线是内部路线时可走生产安排</p></li><li><p>点击进入弹窗设置生产数量</p><p>-生产加工时可使用库存，采购，委外加工，如果生产的这个零件/物料有工艺路线时还可以走生产</p></li><li><p>如果库存满足时可一键使用库存，采购零件也可一键点击设置</p></li><li><p>安排生产时已安排量不能超过需求数量，超过将无法安排</p></li></ul><p><img src="'+a+'" alt="如图所示"></p><h4 id="_3-产品维度走采购" tabindex="-1">3.产品维度走采购 <a class="header-anchor" href="#_3-产品维度走采购" aria-label="Permalink to &quot;3.产品维度走采购&quot;">​</a></h4><ul><li><p>可走采购安排，采购安排的信息会流转到采购管理-缺料列表中进行分发，询价完结等</p></li><li><p>如果这个产品有工艺路线，工艺路线是外部路线时可走采购安排</p></li><li><p>击进入弹窗设置采购数量</p><p>-可直接采购成品或委外加工</p></li><li><p>如果库存满足时可一键使用库存，采购零件也可一键点击设置</p></li><li><p>安排采购时已安排量不能超过需求数量，超过将无法安排</p></li></ul><p><img src="'+i+'" alt="如图所示"></p><h4 id="_2-采购安排-外协加工明细" tabindex="-1">2.采购安排-外协加工明细 <a class="header-anchor" href="#_2-采购安排-外协加工明细" aria-label="Permalink to &quot;2.采购安排-外协加工明细&quot;">​</a></h4><ul><li>没有使用工艺路线的产品，安排采购，使用外协加工时，可手动添加外发配套零件</li></ul><p><img src="'+a+'" alt="如图所示"></p><h4 id="_3-批量安排" tabindex="-1">3.批量安排 <a class="header-anchor" href="#_3-批量安排" aria-label="Permalink to &quot;3.批量安排&quot;">​</a></h4><ul><li><p>安排：只支持相同产品的合并安排</p></li><li><p>库存：在安排中有库存的话可以使用库存来安排</p></li><li><p>采购数量：分为直接采购成品和外协加工</p><p>-外协加工：有工艺路线的产品，安排采购使用外协加工时，可直接带出来所用的零件。没有使用工艺路线的产品，安排采购，使用外协加工时，可手动添加外发配套零件</p></li><li><p>生产数量：可点击工艺路线图标选择路线安排物料（可用库存或者采购），安排完成生产数量会自动带出</p></li></ul><p><img src="'+i+'" alt="如图所示"></p><h2 id="_3-物料维度安排" tabindex="-1">3.物料维度安排 <a class="header-anchor" href="#_3-物料维度安排" aria-label="Permalink to &quot;3.物料维度安排&quot;">​</a></h2><ul><li>可通过编号，单号，名称/型号，开始，结束时间进行查询</li></ul><h4 id="_1-批量安排-1" tabindex="-1">1.批量安排 <a class="header-anchor" href="#_1-批量安排-1" aria-label="Permalink to &quot;1.批量安排&quot;">​</a></h4><ul><li><p>只支持相同物料的合并安排</p></li><li><p>批量安排走库存</p><p>-如果需安排的产品库存满足，可直接使用库存，在对应的库存下面输入安排量，完成后流转至仓库出库所安排的产品</p></li><li><p>批量安排走采购</p><p>-如果安排的产品库存不满足可走采购，输入采购数量，完成以后采购的单子会流转到采购管理的缺料列表里面</p></li><li><p>批量安排走生产</p><p>-如果安排的产品库存不满足，且安排的这个产品有工艺路线的情况下，可走装配（生产），点击弹出弹窗输入装配加工的数量，使用库存（完成需到出库列表中将安排的产品出库）采购（输入采购数量，将流转到采购的缺料列表中进行采购）</p></li></ul><h4 id="_2-安排" tabindex="-1">2.安排 <a class="header-anchor" href="#_2-安排" aria-label="Permalink to &quot;2.安排&quot;">​</a></h4><ul><li><p>点击安排按钮弹出弹窗可安排产品</p></li><li><p>和批量安排操作一样，可使用库存，走代购，走生产</p></li></ul><p><img src="'+d+'" alt="如图所示"></p><h4 id="_3-bom表" tabindex="-1">3.BOM表 <a class="header-anchor" href="#_3-bom表" aria-label="Permalink to &quot;3.BOM表&quot;">​</a></h4><ul><li>点击查看详情可查看这个产品下面挂的组成零件</li></ul><h4 id="_4-相同需求" tabindex="-1">4.相同需求 <a class="header-anchor" href="#_4-相同需求" aria-label="Permalink to &quot;4.相同需求&quot;">​</a></h4><ul><li><p>点击查看详情可查看和这个产品相同的产品</p><p>-页面显示当前这个产品的所有待安排量，可查询后合并安排</p></li></ul><p><img src="'+c+'" alt="如图所示"></p>',44)]))}const w=t(u,[["render",_]]);export{g as __pageData,w as default};
